# 3-SAT -> 3-BOYAMA indirgemesi: kurucu + geri izlemeli dogrulayici.
import itertools

def indirge(fi, n):
    V, E = {}, set()
    def ekle(ad):
        V.setdefault(ad, len(V)); return V[ad]
    T, F, B = ekle("T"), ekle("F"), ekle("B")
    E |= {(T, F), (T, B), (F, B)}
    lit = {}
    for i in range(1, n + 1):
        p, q = ekle("x%d" % i), ekle("~x%d" % i)
        lit[i], lit[-i] = p, q
        E |= {(p, q), (p, B), (q, B)}
    def OR(a, b, etiket):
        u, v, w = ekle(etiket + "u"), ekle(etiket + "v"), ekle(etiket + "w")
        E.update([(a, u), (b, v), (u, v), (u, w), (v, w)])
        return w
    for ci, c in enumerate(fi):
        r1 = OR(lit[c[0]], lit[c[1]], "c%d_1" % ci)
        r2 = OR(r1, lit[c[2]], "c%d_2" % ci)
        E |= {(r2, F), (r2, B)}
    E = {(min(a, b), max(a, b)) for a, b in E}
    return len(V), sorted(E)

def uc_boyanabilir(nv, E):
    komsu = [[] for _ in range(nv)]
    for a, b in E:
        komsu[a].append(b); komsu[b].append(a)
    renk = [-1] * nv
    sira = sorted(range(nv), key=lambda v: -len(komsu[v]))
    def git(i):
        if i == nv:
            return True
        v = sira[i]
        yasak = {renk[u] for u in komsu[v] if renk[u] >= 0}
        for r in range(3):
            if r not in yasak:
                renk[v] = r
                if git(i + 1):
                    return True
                renk[v] = -1
        return False
    return git(0)

def saglanabilir(fi, n):
    return any(all(any(a[abs(l) - 1] == (l > 0) for l in c) for c in fi)
               for a in itertools.product([False, True], repeat=n))

FI0 = [(1, 2, -3), (-1, 2, 3), (1, -2, 3), (-1, -2, -3)]
TUM = [c for c in itertools.product(*[(i, -i) for i in (1, 2, 3)])]

for ad, fi in [("phi0 (m=4)", FI0), ("tum-clause (m=8)", TUM)]:
    nv, E = indirge(fi, 3)
    print("%-18s dugum=%2d  kenar=%2d  3-boyanabilir=%-5s  saglanabilir=%s"
          % (ad, nv, len(E), uc_boyanabilir(nv, E), saglanabilir(fi, 3)))

